class Counters(NetactBase):
    """PM counters"""
    initial_values = None
    final_values = None

    def __init__(self):
        super(Counters, self).__init__()
        self.config = ConfigHandler.get_config()
        self.datetime_ops = DatetimeOperations()
        self.start_date = datetime.now()
        self.default_distname = "PLMN-PLMN/MRBTS-{}".format(get_config_variable(['bts_id']))

    def start_counters(self, **kwargs):
        """Start counter"""
        alias = kwargs.get("alias", 'default')
        dut = kwargs.get("bts_dut", "bts")
        pm_interval = kwargs.get("pm_interval", '15')
        interval_start_extra_wait = kwargs.get('interval_start_extra_wait', 0)
        interval_end_extra_wait = kwargs.get('interval_end_extra_wait', -60)
        self.interval1_starttime, self.interval1_endtime = self._get_interval_start_end_times(dut,
                                                                                              interval_start_extra_wait,
                                                                                              interval_end_extra_wait,
                                                                                              pm_interval, alias)

    def stop_and_verify_counters(self, **kwargs):
        """Stop and verify pm counters"""
        alias = kwargs.pop('alias', 'default')
        dut = kwargs.get("bts_dut", "bts")
        analysis = kwargs.pop('analysis')
        pm_interval = kwargs.get("pm_interval", 15)
        counter_analysis_file = kwargs.pop("counter_analysis_file")
        interval_start_extra_wait = kwargs.get('interval_start_extra_wait', 0)
        interval_end_extra_wait = kwargs.get('interval_end_extra_wait', -60)
        owner = kwargs.pop('owner', 'nokmrn')
        time_shift = kwargs.pop('time_shift', '0')
        self.interval2_starttime, self.interval2_endtime = self._get_interval_start_end_times(dut,
                                                                                              interval_start_extra_wait,
                                                                                              interval_end_extra_wait,
                                                                                              pm_interval, alias)

        self._wait_for_counters_arrival_to_netact(dut, pm_interval)
        return self._get_both_intervals_counters_and_evaluate(analysis, counter_analysis_file, owner, time_shift, alias,
                                                              **kwargs)

    def _get_given_interval_counter_values(self, analysis, counter_analysis_file, owner, time_shift,
                                           interval_starttime, interval_endtime, alias, **kwargs):
        # current_time = self.datetime_ops.get_currenttime_on_enb(dut=dut, time_zone='utc')
        # interval_endtime = current_time - timedelta(seconds=2)
        counter_values = self._get_analysis_structure_filled_with_actuals(analysis, counter_analysis_file,
                                                                          interval_starttime, interval_endtime,
                                                                          owner, time_shift, alias=alias, **kwargs)
        logger.debug("#### counter_values is {}".format(counter_values))
        self._check_if_atleast_one_counter_is_not_none(counter_values)
        return counter_values

    def _get_interval_start_end_times(self, dut, interval_start_extra_wait, interval_end_extra_wait, pm_interval,
                                      alias):
        enb_current_time = self.datetime_ops.get_currenttime_on_enb(dut)
        logger.debug('Current Time On eNB: {}'.format(str(enb_current_time)))
        # logger.debug('Netact Timezone: {}'.format(str(timezone_delta)))
        # current_time = current_time + timezone_delta
        interval_starttime = self.datetime_ops.get_current_interval_start_time(
            current_time=enb_current_time, interval=pm_interval, additional_wait_time=interval_start_extra_wait)
        interval_endtime = self.datetime_ops.wait_for_next_interval(current_time=enb_current_time, interval=pm_interval,
                                                                    additional_wait_time=interval_end_extra_wait)
        # interval_endtime = self.datetime_ops.get_currenttime_on_enb(dut=dut)
        logger.debug('==== PM Interval Startime: {} Endtime: {}'.format(interval_starttime, interval_endtime))
        return interval_starttime, interval_endtime

    # def _get_timezone_difference(self):
    def _round_time(self, time_interval, pm_interval):
        pm_interval = float(pm_interval)
        rounded = time_interval + timedelta(minutes=pm_interval / 2.)
        rounded -= timedelta(minutes=rounded.minute % pm_interval, seconds=rounded.second,
                             microseconds=rounded.microsecond)
        return rounded

    def _check_if_atleast_one_counter_is_not_none(self, counter_values):
        atleast_one_counter_is_not_none = False
        for distname, dist_value in list(counter_values.items()):
            for counter, counter_params in list(dist_value.items()):
                counter_val = counter_values[distname][counter]["value"]
                if counter_val is not None:
                    logger.debug("#### counter value is {}".format(counter_val))
                    atleast_one_counter_is_not_none = True
        else:
            if atleast_one_counter_is_not_none is False:
                raise Exception('None of the given counters are found')

    def _get_analysis_structure_filled_with_actuals(self, analysis, counter_analysis_file, interval_starttime,
                                                    interval_endtime, owner, time_shift, alias, **kwargs):
        counters_analysis_file_content = self._get_json_file_content(counter_analysis_file)
        logger.debug('{}'.format(str(counters_analysis_file_content["counters"][analysis])))
        return self._expand_counters_analysis(analysis, counters_analysis_file_content, interval_starttime,
                                              interval_endtime, owner, time_shift, alias, **kwargs)
        # return counters_analysis_file_content["counters"][analysis]

