    def _get_counter_value(self, technology, measurement, counter, counter_profile_dict, alias, interval_endtime,
                           interval_starttime, mo_names, filter_by, **kwargs):
        counter_value = None
        object_aggregation = kwargs.get("object_aggregation", "PLMN/MRBTS")
        time_aggregation = kwargs.get("time_aggregation", "RAW")
        pm_interval = kwargs.get("pm_interval", 15)
        interval_starttime = self._round_time(interval_starttime, pm_interval)
        interval_endtime = self._round_time(interval_endtime, pm_interval)
        logger.debug("after rounding::\n interval_endtime:" + str(interval_endtime) + "\ninterval_starttime:" + str(
            interval_starttime) + "\ntechnology:" + str(technology) + "\nmeasurement:" + str(
            measurement) + "\ncounters:" + str(counter) + "\nfilter_by:" + str(
            filter_by) + "\nobject_aggregation:" + str(object_aggregation) + "\ntime_aggregation:" + str(
            time_aggregation) + "\nmo_names:" + str(mo_names))

        """
        time_filter = kwargs.pop("time_filter", 'absolute')

        filter_args = {}
        if time_filter == 'absolute':
            filter_args['start_time'] = interval_starttime
            filter_args['end_time'] = interval_endtime
        if time_filter == 'relative':
            filter_args['time_from'] = kwargs['time_from']
            filter_args['time_amount'] = kwargs['time_amount']
            filter_args['time_per.iod'] = kwargs['time_period']
        if time_filter == 'realtime':
            filter_args['look_back_period'] = kwargs['look_back_period']
        """

        # while counter_value is None:
        # counter_name = counter_profile_dict['counter_name']
        logger.debug('========= Counter: {}'.format(counter))
        for attempt in range(1, 16):
            try:

                logger.debug('==== Attempt: {}'.format(attempt))
                counter_value = self.netact_factory.netact.get_pm_counters(technology=technology,
                                                                           measurement=measurement, counters=counter,
                                                                           filter_by=filter_by, mo_names=mo_names,
                                                                           object_aggregation=object_aggregation,
                                                                           time_aggregation=time_aggregation,
                                                                           time_filter='absolute',
                                                                           start_time=interval_starttime,
                                                                           end_time=interval_endtime, alias=alias)
                logger.debug("==== Fetched counter value is {}".format(counter_value))
                if len(counter_value) >= 1:
                    if len(counter_value) == 1:
                        counter_value = counter_value[0]
                    break
                elif len(counter_value) == 0:
                    logger.debug("#### length of counter value is {}".format(len(counter_value)))
                    counter_value = {counter: 0}
                    time.sleep(60)
                    continue
            except Exception as err:
                logger.warn("#### Exception while getting counter value {}".format(err))
                if "BadStatusLine" in str(err):
                    logger.warn("Ignoring the BadStatusLine exception")
                    continue
                logger.warn('Counter {} in {} not available'.format(counter, technology))

        counter_value = counter_value[counter]
        logger.debug('===== counter_value: {}'.format(counter_value))
        return counter_value

    def _get_both_intervals_counters_and_evaluate(self, analysis, counter_analysis_file, owner, time_shift, alias,
                                                  **kwargs):
        Counters.initial_values = self._get_given_interval_counter_values(analysis, counter_analysis_file, owner,
                                                                          time_shift, self.interval1_starttime,
                                                                          self.interval1_endtime, alias, **kwargs)
        logger.debug("First Interval Counters \n{}".format(str(Counters.initial_values)))
        Counters.final_values = self._get_given_interval_counter_values(analysis, counter_analysis_file, owner,
                                                                        time_shift, self.interval2_starttime,
                                                                        self.interval2_endtime, alias, **kwargs)
        logger.debug("Second Interval Counters \n{}".format(str(Counters.final_values)))
        error_flag = self._perform_evaluation(Counters.initial_values, Counters.final_values)
        json_filename = self._save_analysis_to_file(analysis, Counters.final_values)
        if error_flag:
            logger.debug("#### error_flag is {} and counter final value is {}".format(error_flag,
                                                                                      Counters.final_values))
            raise Exception(
                "Atleast one counter validation failed, refer to {} ".format(json_filename))
        else:
            # return counters_ref["counters"][analysis]
            logger.debug("#### error_flag is {} and counter final value is {}".format(error_flag,
                                                                                      Counters.final_values))
            return Counters.final_values

    def _wait_for_counters_arrival_to_netact(self, dut, interval_time):
        
        enb_current_time = self.datetime_ops.get_currenttime_on_enb(dut=dut)
        # wait_mins = (counters_arrival_minute - enb_current_time.minute)
        # if enb_current_time.minute > 45:
        #     wait_mins += 60
        wait_mins = 0
        interval_time = int(interval_time)
        logger.debug("######### enb_current_time minute : {}".format(enb_current_time.minute))
        if enb_current_time.minute % interval_time != 0:
            wait_mins = interval_time - (enb_current_time.minute % interval_time)
        wait_seconds = (wait_mins + 1) * 60
        logger.debug('==== Waiting {} for counters arrival on Netact'.format(str(timedelta(seconds=wait_seconds))))
        time.sleep(wait_seconds)

    def _save_analysis_to_file(self, analysis, final_values):
        json_filename = 'execution_logs/{}_{}_counters.json'.format(
            analysis, config_utils.get_config_variable(["bts_id"]))
        logger.debug("Analysis Json file :: {}".format(str(json_filename)))
        if not os.path.exists(os.path.dirname(json_filename)):
            os.makedirs(os.path.dirname(json_filename))
        # self._write_to_json_file(counters_ref["counters"][analysis], json_filename)
        self._write_to_json_file(final_values, json_filename)
        return json_filename

    def _perform_evaluation(self, initial_values_struct, final_values_struct):
        error_flag = False
        logger.debug('#### Final values :: {}'.format(final_values_struct))
        # for distname, dist_value in final_values_struct["counters"][analysis].iteritems():
        logger.debug('==== Evaluation Result')
        for distname, dist_value in list(final_values_struct.items()):
            for counter, counter_value in list(dist_value.items()):
                logger.debug('==== Counter: {} ========'.format(counter))
                logger.debug('==== Counter Value: {} ======='.format(counter_value))
                initial_val = initial_values_struct[distname][counter]["value"]
                final_val = counter_value["value"]
                analysis_type = counter_value["analysis_type"].lower()
                output = self._get_analysis_output(initial_val, final_val, analysis_type)
                lower_bound, upper_bound = self._get_boundary_values(counter_value)
                logger.debug('\texpected_val: {} output_val: {}'.format(counter_value["expected_value"], str(output)))
                counter_value["output"] = output
                counter_value["initial_counter_value"] = initial_val
                counter_value["final_counter_value"] = final_val
                result, error_flag = self._get_verdict(output, lower_bound, upper_bound)
                counter_value["result"] = result
        return error_flag

    def _get_verdict(self, output, lower_bound, upper_bound):
        result = 'Pass'
        error_flag = False
        if output is not None:
            if lower_bound <= output <= upper_bound:
                result = "Pass"
            else:
                result = "Failed - Output: {}, Not in Given Range".format(output)
                error_flag = True
        else:
            result = "Failed - None or Ambiguous value in  initial_val or final_val "
            error_flag = True
        return result, error_flag

    def _get_boundary_values(self, counter_value):
        lower_bound, upper_bound = self._convert_range(counter_value["expected_value"])
        lower_bound = int(int(lower_bound) - (float(counter_value["tolerance"]) / 100.0 * int(lower_bound)))
        if not upper_bound == sys.maxsize:
            upper_bound = int(int(upper_bound) + (float(counter_value["tolerance"]) / 100.0 * int(upper_bound)))
        # logger.debug('lower bound: {} upper bound: {}'.format(str(lower_bound), str(upper_bound)))
        return lower_bound, upper_bound

    def _get_analysis_output(self, initial_val, final_val, analysis_type):
        # Check None condition if required
        output = None
        if initial_val is not None and final_val is not None:
            if not isinstance(initial_val, list) and not isinstance(final_val, list):
                if analysis_type == "diff":
                    output = int(final_val) - int(initial_val)
                elif analysis_type == "current":
                    output = int(final_val)
        return output

    def _get_json_file_content(self, analysis_file):
        counters_analysis_dict = {}
        counters_analysis_files = [os.path.join(self.config['common_resources_path'],
                                                analysis_file),
                                   os.path.join(self.config['feature_resources_path'],
                                                analysis_file)]
        logger.debug("####### counters_analysis_files {}".format(counters_analysis_files))
        for counters_analysis_file in counters_analysis_files:
            if os.path.exists(counters_analysis_file):
                with open(counters_analysis_file, "r") as file_handle:
                    counters_analysis_dict.update(json.load(file_handle))
        return counters_analysis_dict

    def _get_result(self, c_value_dict, counter_val, error_flag):
        counterval_list = counter_val
        output = None
        if c_value_dict["analysis_type"].lower() == "diff":
            output = sum(counterval_list) - counterval_list[-1]
        elif c_value_dict["analysis_type"].lower() == "current":
            logger.debug("### counterval_list from _get_result is {} and its sum is {}".format(counterval_list,
                                                                                               sum(counterval_list)))
            output = sum(counterval_list)
        lower_bound, upper_bound = self._convert_range(c_value_dict["expected_value"])
        lower_bound = int(int(lower_bound) - (float(c_value_dict["tolerance"]) / 100.0 * int(lower_bound)))
        if not upper_bound == sys.maxsize:
            logger.debug("#### new calculation for maxsize in _get_result")
            upper_bound = int(int(upper_bound) + (float(c_value_dict["tolerance"]) / 100.0 * int(upper_bound)))
        logger.debug('lower bound: {} upper bound: {}'.format(lower_bound, upper_bound))
        logger.debug('expected val: {} output val: {}'.format(c_value_dict["expected_value"], output))
        if int(lower_bound) <= output <= int(upper_bound):
            c_value_dict["result"] = "Pass"
            c_value_dict["output_val"] = output
            c_value_dict["final_counter_value"] = sum(counter_val)
        else:
            c_value_dict["result"] = "Failed - Evaluation Failed"
            c_value_dict["output_val"] = output
            c_value_dict["final_counter_value"] = sum(counter_val)
            error_flag = True
        return error_flag

    def _convert_range(self, range_value):
        response = list(re.split(r'\.\.', range_value))
        if len(response) == 2:
            if response[0].strip() == '*':
                lower_bound = -sys.maxsize - 1  # -2147483648
            else:
                lower_bound = int(response[0])
            if response[1].strip() == '*':
                upper_bound = sys.maxsize
            else:
                upper_bound = int(response[1])
        elif len(response) == 1:
            upper_bound = lower_bound = int(response[0])
        else:
            return 0

        return lower_bound, upper_bound

    def _write_to_json_file(self, final_value, json_filename):
        with open(json_filename, 'w') as j_file:
            json.dump(final_value, j_file)
